import 'package:flutter/foundation.dart';
import 'package:games_services/games_services.dart';

/// The game's Google Play Games Services leaderboards (Android only — no
/// iOS build for this game).
enum Board {
  /// Highest level cleared.
  highestLevel('CgkIhc2n1OMREAIQAg'),

  /// Largest number reached in a single run (peak, before walls/stairs
  /// spend it).
  biggestNumber('CgkIhc2n1OMREAIQAw');

  const Board(this.androidId);

  /// Opaque ID generated by Play Console when the leaderboard is created.
  final String androidId;

  bool get isConfigured => !androidId.startsWith('REPLACE_');
}

/// Pattern copied from block-puzzle-app's LeaderboardService, which is
/// confirmed working on live Play Store installs:
///
/// - Every call is try/catch'd: without full Play Console setup (or with no
///   Google account / Play Services / network) sign-in, submit and show
///   all fail, and that must never crash or block gameplay.
/// - Every platform call also has a `.timeout`: these are plain
///   MethodChannel calls whose Futures can hang forever instead of
///   throwing (seen under flutter_test, same failure class as the
///   flame_audio pool hang in SoundService).
/// - The timeout is 12s, not 5s: a *first-ever* sign-in can show an
///   interactive Google consent sheet, and a tight timeout killed the
///   attempt before the player could tap it.
///
/// Live-only failure checklist: Play App Signing re-signs the app, so the
/// Play Games credentials need the *app signing key's* SHA-1 registered
/// too, not just the upload key's.
class LeaderboardService {
  static const _timeout = Duration(seconds: 12);

  static bool get _isSupported => !kIsWeb && defaultTargetPlatform == TargetPlatform.android;

  static bool get _anyConfigured => Board.values.any((b) => b.isConfigured);

  /// Silent sign-in, attempted when a game starts. Play Games v2 also
  /// auto-prompts, but the plugin requires this before submit/show.
  static Future<void> signIn() async {
    if (!_isSupported || !_anyConfigured) return;
    try {
      await GameAuth.signIn().timeout(_timeout);
    } catch (_) {}
  }

  /// Fire-and-forget; Play Games keeps only the best score per player.
  static Future<void> submit(Board board, int value) async {
    if (!_isSupported || !board.isConfigured || value <= 0) return;
    try {
      await Leaderboards.submitScore(
        score: Score(androidLeaderboardID: board.androidId, value: value),
      ).timeout(_timeout);
    } catch (_) {}
  }

  /// Opens Play Games' own list of all this game's leaderboards. Returns
  /// whether it could, so the caller can say "not available" instead of
  /// silently doing nothing after an explicit tap.
  static Future<bool> showAll() async {
    if (!_isSupported || !_anyConfigured) return false;
    try {
      await GameAuth.signIn().timeout(_timeout);
      await Leaderboards.showLeaderboards().timeout(_timeout);
      return true;
    } catch (_) {
      return false;
    }
  }
}
